create or replace function public.execute_v19_stock_transfer(p_transfer_id uuid,p_action text) returns jsonb language plpgsql security definer set search_path=public as $fn$ declare t public.stock_transfers; begin select * into t from public.stock_transfers where id=p_transfer_id for update; if t.id is null then raise exception 'Stock transfer not found'; end if; if lower(p_action)='cancel' then if t.status <> 'draft' then raise exception 'Only draft transfers can be cancelled'; end if; update public.stock_transfers set status='cancelled',cancelled_at=now() where id=t.id; return jsonb_build_object('transfer_id',t.id,'status','cancelled'); end if; raise exception 'V2.1 execution guard requires the complete transfer executor'; end $fn$; grant execute on function public.execute_v19_stock_transfer(uuid,text) to authenticated;